// src/lib/boss-names.ts
function bossPresentation(slug) {
  return bosses_default[slug];
}
var bossNameMappings = { "ultra-drago": { displayName: "King Draco", canonicalSourceName: "King Drago", encounterName: "Ultra Drago", mapCommand: "/join ultradrago", source: "https://aqwwiki.wikidot.com/king-drago-monster" } };
function bossDisplayName(slug, name) {
  return bossPresentation(slug)?.officialName || name;
}
function monsterDisplayName(monster) {
  return monster.canonicalName === "King Drago" && monster.source?.includes("king-drago-monster") ? "King Draco" : monster.canonicalName;
}

