// src/lib/speaker-strategies.ts
var speakerStrategies = speaker_strategies_default;
function rotationPages(steps) {
  const pages = [{ label: "M\u1EDF \u0111\u1EA7u", steps: steps.slice(0, 2) }];
  for (let i = 2; i < steps.length; i += 4)
    pages.push({
      label: `${String(i + 1).padStart(2, "0")}\u2013${String(Math.min(i + 4, steps.length)).padStart(2, "0")}`,
      steps: steps.slice(i, i + 4)
    });
  return pages;
}
function selectedSpeakerClass(slot, selected) {
  return [slot.primaryClass, ...slot.alternativeClasses].find(
    (c) => c.classId === selected[slot.id]
  ) || slot.primaryClass;
}
function speakerAssignment(raw, strategy, selected) {
  if (raw === "\u2014") return { label: raw, tip: "" };
  const allowed = raw.replace(/\([^)]*\)/g, "").trim().split("/").map((s) => s.trim());
  const slot = raw.startsWith("mDPS") ? strategy.classSlots[0] : strategy.classSlots.find(
    (s) => [s.primaryClass, ...s.alternativeClasses].some(
      (c) => allowed.includes(c.abbreviation)
    )
  );
  if (!slot)
    return { label: raw, tip: "Gi\u1EEF \u0111\xFAng ph\xE2n c\xF4ng \u0111\u01B0\u1EE3c ghi trong b\u1EA3ng." };
  const choice = selectedSpeakerClass(slot, selected);
  const suffix = raw.match(/\([^)]+\)/)?.[0] || "";
  const equivalent = raw.startsWith("mDPS") || allowed.includes(choice.abbreviation);
  const tip = /Prax/.test(suffix) ? "Canh Praxis \u0111\u1EC3 ch\u1EB7n s\xE1t th\u01B0\u01A1ng; kh\xF4ng \u0111\u1ED5i th\u1EDDi \u0111i\u1EC3m \u0111\xE3 ph\xE2n c\xF4ng." : suffix === "(3)" ? "CAv d\xF9ng skill 3 \u0111\u1EC3 Taunt t\u1EA1i l\u01B0\u1EE3t n\xE0y." : suffix === "(4)" ? "LP d\xF9ng skill 4, c\u1EA7n Spirits t\u1EEB skill 3; canh \u0111\xFAng l\u01B0\u1EE3t." : equivalent ? choice.name : `B\u1EA3ng ch\u1EC9 x\xE1c minh ${raw}; ch\u01B0a c\xF3 bi\u1EBFn th\u1EC3 ri\xEAng cho ${choice.abbreviation}. Kh\xF4ng t\u1EF1 \u0111\u1ED5i ng\u01B0\u1EDDi nh\u1EADn l\u01B0\u1EE3t.`;
  return {
    label: equivalent ? choice.abbreviation + (suffix ? " " + suffix : "") : raw,
    tip
  };
}

